        } catch (ClassNotFoundException e) {
            throw new IOException("formato desconhecido", e);
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp) throws IOException {
        String cliente = clienteAtual(req);
