#!/usr/bin/env bash
set -euo pipefail

DB_HOST="${DB_HOST:-127.0.0.1}"
DB_USER="${DB_USER:-backup}"
DEFAULTS_FILE="${DEFAULTS_FILE:-/etc/backup/my.cnf}"  # [client] password=..., modo 0600
DEST="${DEST:-/var/backups/mysql}"
KEEP_DAYS=14

list_databases() {
    mysql --defaults-extra-file="$DEFAULTS_FILE" -h "$DB_HOST" -u "$DB_USER" -N -e 'SHOW DATABASES' \
        | grep -Ev '^(information_schema|performance_schema|sys)$'
}

dump_one() {
    local db="$1"
    mysqldump --defaults-extra-file="$DEFAULTS_FILE" -h "$DB_HOST" -u "$DB_USER" --single-transaction "$db" \
        | gzip > "$DEST/${db}-$(date +%F).sql.gz"
}

rotate() {
    find "$DEST" -name '*.sql.gz' -mtime +"$KEEP_DAYS" -delete
}

[[ "$(stat -c %a "$DEFAULTS_FILE")" == 600 ]] || { echo "permissao insegura em $DEFAULTS_FILE" >&2; exit 1; }
mkdir -p "$DEST"
for db in $(list_databases); do
    echo "dump: $db"
    dump_one "$db"
done
rotate

